import math

p, q = 0.55, 0.45

def g(f):
    return p * math.log(1 + f) + q * math.log(1 - f)

best_f, best_g = 0, g(0)
f = 0.0001
while f < 0.999:
    val = g(f)
    if val > best_g:
        best_f, best_g = f, val
    f += 0.0001

print(round(best_f, 3))   # 0.1 (matches f* = p - q = 0.10)
